pub fn confLoad(allo: std.mem.Allocator, iozz: std.Io, path: []const u8) !Conf { const byte = std.Io.Dir.cwd().readFileAlloc(iozz, path, allo, .limited(CF.maxz)) catch |err| { if (err == error.FileNotFound) return .{}; return err; }; return confParse(allo, byte); }
pub fn confKeyz(allo: std.mem.Allocator, byte: []const u8) ?[]const u8 { const valu = std.json.parseFromSliceLeaky(std.json.Value, allo, byte, .{}) catch return null; if (valu != .object) return null; var iter = valu.object.iterator(); while (iter.next()) |item| { var known = false; inline for (@typeInfo(Conf).@"struct".field_names) |fnam| { if (std.mem.eql(u8, fnam, item.key_ptr.*)) known = true; } if (!known) return item.key_ptr.*; } return null; }
pub fn confParse(allo: std.mem.Allocator, byte: []const u8) !Conf { if (confKeyz(allo, byte)) |keyz| { std.debug.print("config error: unknown key \"{s}\" (fix the name or remove it)\n", .{keyz}); return error.BadConfig; } const conf = std.json.parseFromSliceLeaky(Conf, allo, byte, .{ .ignore_unknown_fields = false, .allocate = .alloc_always }) catch return error.BadConfig; try confChek(conf); return conf; }
pub fn confChek(conf: Conf) !void { if ((conf.brow_wind_widt == 0) != (conf.brow_wind_high == 0) or conf.brow_wind_widt > 10000 or conf.brow_wind_high > 10000 or !std.math.isFinite(conf.brow_wind_scal) or (conf.brow_wind_scal != 0 and (conf.brow_wind_scal < 0.25 or conf.brow_wind_scal > 4)) or conf.brow_wind_left < -100 or conf.brow_wind_left > 10000) return error.BadConfig; if (conf.feed_item_maxz == 0 or conf.feed_item_maxz > 5000 or conf.feed_text_maxz < 200) return error.BadConfig; for (conf.feed_chat_list) |chat| { if (std.mem.trim(u8, chat, " ").len == 0) return error.BadConfig; } if (conf.rand_seed_fixd != 0) return error.BadConfig; if (conf.type_dely_msec[0] < 30 or conf.type_dely_msec[1] * 2 < conf.type_dely_msec[0] * 3) return error.BadConfig; if (conf.acti_dely_secs[0] < 2 or conf.acti_dely_secs[1] <= conf.acti_dely_secs[0]) return error.BadConfig; if (conf.read_dely_msec[0] < 200 or conf.read_dely_msec[1] * 2 < conf.read_dely_msec[0] * 3) return error.BadConfig; if (conf.capz_send_hour == 0 or conf.capz_send_dayz == 0 or conf.capz_send_dayz < conf.capz_send_hour or conf.capz_send_minu == 0) return error.BadConfig; if (conf.quie_hour_rang[0] > 23 or conf.quie_hour_rang[1] > 23) return error.BadConfig; if (conf.loca_utcz_mins < -720 or conf.loca_utcz_mins > 840) return error.BadConfig; if (conf.retr_coun_maxz == 0 or conf.retr_coun_maxz > 9 or conf.read_msgz_maxz == 0 or conf.brow_time_secs == 0) return error.BadConfig; if (conf.gapz_send_msec < 1000) return error.BadConfig; if (conf.smar_chai_orde.len == 0) return error.BadConfig; for (conf.smar_chai_orde) |item| if (!std.mem.eql(u8, item, "clau") and !std.mem.eql(u8, item, "llam")) return error.BadConfig; if (conf.acct_maxx_coun == 0 or conf.acct_maxx_coun > 20 or conf.acct_gap_secs[0] > conf.acct_gap_secs[1] or conf.aliv_look_hour == 0 or conf.aliv_look_hour > 72 or conf.secr_loca_main.len == 0) return error.BadConfig; }
pub fn dataRoot(cfg: Conf, windows: bool) []const u8 { return if (windows) cfg.data_loca_wind else cfg.data_loca_unix; }
pub fn pathHome(allo: std.mem.Allocator, home: []const u8, path: []const u8) ![]u8 { if (std.mem.startsWith(u8, path, "~/") or std.mem.startsWith(u8, path, "~\\")) return std.fs.path.join(allo, &.{ home, path[2..] }); if (std.mem.eql(u8, path, "~")) return allo.dupe(u8, home); return allo.dupe(u8, path); }
